<?php
namespace App\Domain\Integrity\Services; use App\Domain\Integrity\Models\{IntegrityAuditRun,IntegrityAuditFinding}; use App\Domain\Leaderboards\Models\LeaderboardEntry; use App\Domain\Leaderboards\Services\LeaderboardService; use App\Domain\Races\Models\RaceRun; use App\Models\User;
class LeaderboardIntegrityService { public function __construct(private readonly LeaderboardService $leaderboards){} public function audit(bool $dryRun=true,?User $by=null):IntegrityAuditRun{$audit=IntegrityAuditRun::create(['audit_type'=>'leaderboard','dry_run'=>$dryRun,'status'=>'running','started_by'=>$by?->id,'started_at'=>now()]);LeaderboardEntry::with('raceRun')->each(function($entry)use($audit,$dryRun){$valid=$entry->raceRun&&$entry->raceRun->isAccepted()&&$entry->best_duration_ms===$entry->raceRun->duration_ms;if(!$valid){IntegrityAuditFinding::create(['integrity_audit_run_id'=>$audit->id,'severity'=>'error','subject_type'=>'leaderboard_entry','subject_id'=>$entry->id,'details_json'=>['reason'=>'missing_or_invalid_accepted_run'],'repaired'=>!$dryRun]);if(!$dryRun)$entry->delete();}});$count=IntegrityAuditFinding::where('integrity_audit_run_id',$audit->id)->count();$audit->update(['status'=>'completed','findings_count'=>$count,'repairs_count'=>$dryRun?0:$count,'completed_at'=>now()]);return $audit->refresh();} public function rebuild(bool $dryRun=true):IntegrityAuditRun{$audit=IntegrityAuditRun::create(['audit_type'=>'leaderboard_rebuild','dry_run'=>$dryRun,'status'=>'running','started_at'=>now()]);if(!$dryRun){LeaderboardEntry::query()->delete();RaceRun::where('status',RaceRun::STATUS_ACCEPTED)->each(fn($r)=>$this->leaderboards->recordAcceptedRun($r));}$audit->update(['status'=>'completed','completed_at'=>now()]);return $audit->refresh();} public function repairEntry(LeaderboardEntry $entry,bool $dryRun=true):bool{if($dryRun)return true;$entry->delete();if($entry->raceRun?->isAccepted())$this->leaderboards->recordAcceptedRun($entry->raceRun);return true;} }
